// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }
    function testFuzz_property(uint256 seed) public {
        // Admissible caller must be a contract exposing supportsToken() with the expected hash.
        // Route the interaction through a deployed helper embodying that counterparty;
        // the fuzzed seed varies the test environment (nonce/timestamp domain) broadly.
        Caller caller = new Caller{salt: bytes32(seed)}(c);
        vm.warp(1000 + (seed % 1000));
        bool ok;
        try caller.go() { ok = true; } catch { ok = false; }
        // Rule: for every admissible caller, airDrop completes and its balance becomes exactly 20.
        assertTrue(ok && c.tokenBalance(address(caller)) == 20);
    }
}

contract Caller {
    ModifierEntrancy c;
    constructor(ModifierEntrancy _c) { c = _c; }
    function supportsToken() external view returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
    function go() external {
        c.airDrop();
    }
}
